DATE_LABEL_RE = re.compile(r"\b(DATE|DATED)\b", re.IGNORECASE)
DATE_PATTERNS = [
    (re.compile(r"\b(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})\b"), "dmy"),
    (re.compile(r"\b(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})\b"), "ymd"),
]


def _plausible(y, m, d):
    try:
        y, m, d = int(y), int(m), int(d)
    except Exception:
        return False
    if y < 100:
        y += 2000
    if y < 2000 or y > 2035:
        return False
    if not (1 <= m <= 12):
        return False
    if not (1 <= d <= 31):
        return False
    return True


def _to_iso(y, m, d):
    y, m, d = int(y), int(m), int(d)
    if y < 100:
        y += 2000
    return f"{y:04d}-{m:02d}-{d:02d}"


def extract_dates_from_line(line):
    out = []
    for regex, order in DATE_PATTERNS:
        for m in regex.finditer(line):
            a, b, c = m.group(1), m.group(2), m.group(3)
            if order == "dmy":
                if _plausible(c, b, a):
