import os
import re
import glob
import pytesseract
from PIL import Image, ImageOps
from openpyxl import Workbook

IMG_DIR = "/app/workspace/dataset/img"
OUT_XLSX = "/app/workspace/stat_ocr.xlsx"

EXCLUDE_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "SUB-TOTAL",
    "TAX", "GST", "SST",
    "DISCOUNT", "CHANGE", "CASH TENDERED",
]

# Priority groups (highest first).
KEYWORD_GROUPS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
]

# Match numbers with optional comma thousands and optional decimals
# (tolerates spaces around the decimal separator).
AMOUNT_RE = re.compile(
    r"(?<![\w.])(\d{1,3}(?:,\d{3})+(?:\s*\.\s*\d{1,2})?|\d+\s*\.\s*\d{1,2}|\d+)(?![\w])"
)


def clean_spaced_decimals(line):
    """Collapse spaces between digit.space.digit patterns: '49. 40' -> '49.40'."""
    return re.sub(r"(\d)\s*\.\s*(\d{1,2})(?!\d)", r"\1.\2", line)


def ocr_text(image_path):
    img = Image.open(image_path)
    g = ImageOps.autocontrast(ImageOps.grayscale(img))
    return pytesseract.image_to_string(g, lang='eng', config='--psm 6')


def normalize_amount(s):
    if s is None:
        return None
    s = str(s).strip().replace(",", "").replace(" ", "")
    if not s:
        return None
    m = re.search(r"(\d+)(?:\.(\d{1,2}))?$", s)
    if not m:
        return None
    whole = m.group(1)
    frac = (m.group(2) or "00").ljust(2, "0")
    return f"{int(whole)}.{frac[:2]}"


def is_excluded(line_upper):
    for kw in EXCLUDE_KEYWORDS:
        if kw in line_upper:
            return True
    return False


def find_amounts_in_line(line):
    line = clean_spaced_decimals(line)
    return [m.group(1).replace(" ", "") for m in AMOUNT_RE.finditer(line)]


def pick_amount(amounts):
    """Prefer decimal amount; otherwise last number."""
    if not amounts:
        return None
    decs = [a for a in amounts if "." in a]
    return decs[-1] if decs else amounts[-1]


def extract_total(text):
    lines = text.splitlines()
    n = len(lines)
    for group in KEYWORD_GROUPS:
        for i, line in enumerate(lines):
            up = line.upper()
            if is_excluded(up):
                continue
            if not any(kw in up for kw in group):
                continue
            amounts = find_amounts_in_line(line)
            picked = pick_amount(amounts)
            if picked:
                return normalize_amount(picked)
            # Fallback: last number on the next non-empty line.
            j = i + 1
            while j < n and not lines[j].strip():
                j += 1
            if j < n:
                next_up = lines[j].upper()
                if not is_excluded(next_up):
                    nxt = find_amounts_in_line(lines[j])
                    picked = pick_amount(nxt)
                    if picked:
                        return normalize_amount(picked)
    return None


DATE_LABEL_RE = re.compile(r"\b(DATE|DATED|INVOICE\s*DATE|DOC\s*DATE)\b", re.IGNORECASE)

DATE_PATTERNS = [
    (re.compile(r"\b(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})\b"), "dmy"),
    (re.compile(r"\b(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})\b"), "ymd"),
]


def _plausible(y, m, d):
    try:
        y, m, d = int(y), int(m), int(d)
    except Exception:
        return False
    if y < 100:
        y += 2000
    if y < 2000 or y > 2035:
        return False
    if not (1 <= m <= 12):
        return False
    if not (1 <= d <= 31):
        return False
    return True


def _to_iso(y, m, d):
    y, m, d = int(y), int(m), int(d)
    if y < 100:
        y += 2000
    return f"{y:04d}-{m:02d}-{d:02d}"


def extract_dates_from_line(line):
    out = []
    for regex, order in DATE_PATTERNS:
        for m in regex.finditer(line):
            a, b, c = m.group(1), m.group(2), m.group(3)
            if order == "dmy":
                if _plausible(c, b, a):
                    out.append(_to_iso(c, b, a))
            else:
                if _plausible(a, b, c):
                    out.append(_to_iso(a, b, c))
    return out


def extract_date(text):
    lines = text.splitlines()
    labeled = []
    unlabeled = []
    for idx, ln in enumerate(lines):
        has_label = bool(DATE_LABEL_RE.search(ln))
        for iso in extract_dates_from_line(ln):
            if has_label:
                labeled.append((idx, iso))
            else:
                unlabeled.append((idx, iso))
    if labeled:
        return labeled[0][1]
    if unlabeled:
        return unlabeled[0][1]
    return None


def process():
    files = sorted(glob.glob(os.path.join(IMG_DIR, "*")))
    results = []
    for fp in files:
        fn = os.path.basename(fp)
        try:
            text = ocr_text(fp)
            total = extract_total(text)
            date = extract_date(text)
        except Exception as e:
            print(f"ERROR {fn}: {e}")
            total = None
            date = None
        print(f"{fn}\tdate={date}\ttotal={total}")
        results.append((fn, date, total))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fn, d, t in results:
        ws.append([fn, d, t])
    wb.save(OUT_XLSX)
    print(f"Saved {OUT_XLSX}")


