    r"\b(TOTAL\s+(QTY|ITEM|ITEMS)|ITEM\s+COUNT|TOTAL\s+QTY\.)\b", re.IGNORECASE
)
COLUMN_HDR_WORDS = ["QTY", "PRICE", "DESCRIPTION", "DESC", "ITEM NAME",
                    "S/PRICE", "U/PRICE", "RSP", "UNIT PRICE"]

# Priority groups (highest first), sub-ordered by specificity within group.
KEYWORD_GROUPS = [
    [r"GRAND\s+TOTAL"],
    [r"TOTAL\s*[:\(]?\s*\(?RM\)?"],  # TOTAL RM, TOTAL: RM, TOTAL (RM)
    [r"TOTAL\s+AMOUNT", r"TOTAL\s+AMT"],
    [r"NETT?\s+TOTAL", r"TOTAL\s+DUE", r"AMOUNT\s+DUE", r"AMT\s+DUE",
     r"BALANCE\s+DUE", r"TOTAL", r"AMOUNT"],
]


def ocr_variants(image_path):
    img = Image.open(image_path)
    texts = []
    g = ImageOps.autocontrast(ImageOps.grayscale(img))
    texts.append(("psm6", pytesseract.image_to_string(g, lang='eng', config='--psm 6')))
    texts.append(("raw", pytesseract.image_to_string(img, lang='eng')))
    if min(img.size) < 900:
        big = img.resize((img.size[0] * 2, img.size[1] * 2))
        big = ImageOps.autocontrast(ImageOps.grayscale(big))
        texts.append(("up2", pytesseract.image_to_string(big, lang='eng', config='--psm 6')))
    return texts


def clean_spaced_decimals(line):
    line = re.sub(r"(\d)\s*\.\s*(\d{1,2})(?!\d)", r"\1.\2", line)
    # Colon between digits sometimes means decimal (e.g., 92:80 -> 92.80),
    # but avoid touching HH:MM times. Only treat as decimal when followed by
    # a non-digit or end.
    return line


AMOUNT_RE = re.compile(
    r"(?<![\w.])(\d{1,3}(?:,\d{3})+(?:\.\d{1,2})?|\d+\.\d{1,2}|\d+)(?!\w)"
)


def find_amounts_in_line(line):
    line = clean_spaced_decimals(line)
    return [m.group(1).replace(",", "") for m in AMOUNT_RE.finditer(line)]


def pick_amount(amounts):
    if not amounts:
        return None
    decs = [a for a in amounts if "." in a]
    return decs[-1] if decs else amounts[-1]


def is_excluded(line_upper):
    for kw in EXCLUDE_KEYWORDS:
        if kw in line_upper:
            return True
    if QTY_EXCLUSION_RE.search(line_upper):
        return True
    return False


def is_column_header(line_upper):
    count = sum(1 for w in COLUMN_HDR_WORDS if w in line_upper)
    # "AMOUNT" by itself is OK; only treat as header if 2+ column-label words present.
    if "AMOUNT" in line_upper and count >= 1:
        return True
    return count >= 2


def normalize_amount(s):
    if s is None:
        return None
    s = str(s).strip().replace(",", "").replace(" ", "")
    if not s:
        return None
    m = re.search(r"(\d+)(?:\.(\d{1,2}))?$", s)
    if not m:
        return None
    whole = m.group(1)
    frac = (m.group(2) or "00").ljust(2, "0")
    return f"{int(whole)}.{frac[:2]}"


def extract_total_from_text(text):
    lines = text.splitlines()
    n = len(lines)
    for group in KEYWORD_GROUPS:
        for kw_regex in group:
            pattern = re.compile(kw_regex, re.IGNORECASE)
            for i, line in enumerate(lines):
                up = line.upper()
                if is_excluded(up):
                    continue
                if is_column_header(up):
                    # Column header matched; skip to avoid picking item amounts.
                    continue
                if not pattern.search(line):
                    continue
                amounts = find_amounts_in_line(line)
                picked = pick_amount(amounts)
                if picked:
                    return normalize_amount(picked)
                # Fallback: last number on next non-empty, non-excluded line.
                j = i + 1
                while j < n and not lines[j].strip():
                    j += 1
                if j < n:
                    nxt_up = lines[j].upper()
                    if not is_excluded(nxt_up):
                        picked = pick_amount(find_amounts_in_line(lines[j]))
                        if picked:
                            return normalize_amount(picked)
    return None


DATE_LABEL_RE = re.compile(r"\b(DATE|DATED)\b", re.IGNORECASE)
DATE_PATTERNS = [
    (re.compile(r"\b(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})\b"), "dmy"),
    (re.compile(r"\b(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})\b"), "ymd"),
]


def _plausible(y, m, d):
    try:
        y, m, d = int(y), int(m), int(d)
    except Exception:
        return False
    if y < 100:
        y += 2000
    if y < 2000 or y > 2035:
        return False
    if not (1 <= m <= 12):
        return False
    if not (1 <= d <= 31):
        return False
    return True


def _to_iso(y, m, d):
    y, m, d = int(y), int(m), int(d)
    if y < 100:
        y += 2000
    return f"{y:04d}-{m:02d}-{d:02d}"


def extract_dates_from_line(line):
    out = []
    for regex, order in DATE_PATTERNS:
        for m in regex.finditer(line):
            a, b, c = m.group(1), m.group(2), m.group(3)
            if order == "dmy":
                if _plausible(c, b, a):
                    out.append(_to_iso(c, b, a))
            else:
                if _plausible(a, b, c):
                    out.append(_to_iso(a, b, c))
    return out


def extract_date_from_text(text):
    lines = text.splitlines()
    labeled, unlabeled = [], []
    for idx, ln in enumerate(lines):
        has_label = bool(DATE_LABEL_RE.search(ln))
        for iso in extract_dates_from_line(ln):
            if has_label:
                labeled.append((idx, iso))
            else:
                unlabeled.append((idx, iso))
    if labeled:
        return labeled[0][1]
    if unlabeled:
        return unlabeled[0][1]
    return None


def vote(candidates):
    """Return majority; break ties by preserving order of first appearance."""
    cleaned = [c for c in candidates if c]
    if not cleaned:
        return None
    counts = Counter(cleaned)
    best = counts.most_common(1)[0][1]
    for c in cleaned:  # earliest with best count
        if counts[c] == best:
            return c
    return cleaned[0]


def process():
    files = sorted(glob.glob(os.path.join(IMG_DIR, "*")))
    results = []
    for fp in files:
        fn = os.path.basename(fp)
        try:
            variants = ocr_variants(fp)
            per_variant = {}
            for name, text in variants:
                per_variant[name] = (
                    extract_date_from_text(text),
                    extract_total_from_text(text),
                )
            dates = [v[0] for v in per_variant.values()]
            totals = [v[1] for v in per_variant.values()]
            date = vote(dates)
            total = vote(totals)
        except Exception as e:
            print(f"ERROR {fn}: {e}")
            date = None
            total = None
        print(f"{fn}\tdate={date}\ttotal={total}\tvariants={per_variant}")
        results.append((fn, date, total))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fn, d, t in results:
        ws.append([fn, d, t])
    wb.save(OUT_XLSX)
    print(f"Saved {OUT_XLSX}")


if __name__ == "__main__":
    process()
