import os
import re
import glob
import pytesseract
from PIL import Image, ImageOps, ImageFilter
from openpyxl import Workbook

IMG_DIR = "/app/workspace/dataset/img"
OUT_XLSX = "/app/workspace/stat_ocr.xlsx"

EXCLUDE_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "SUB-TOTAL",
    "TAX", "GST", "SST",
    "DISCOUNT", "CHANGE", "CASH TENDERED",
    "TOTAL ITEM", "TOTAL ITEMS", "ITEM COUNT", "TOTAL QTY",
]

# Keyword priority groups (highest priority first).
KEYWORD_GROUPS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM", "TOTAL(RM)", "TOTAL (RM)"],
    ["TOTAL AMOUNT"],
    ["NETT TOTAL", "NET TOTAL", "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE"],
    ["TOTAL"],
    ["AMOUNT"],
]

AMOUNT_RE = re.compile(r"(?<![\d.])\d{1,3}(?:,\d{3})*(?:\.\d{1,2})?|(?<![\d.])\d+\.\d{1,2}")


def ocr_variants(image_path):
    img = Image.open(image_path)
    texts = []
    # Raw default.
    texts.append(pytesseract.image_to_string(img, lang='eng'))
    # Baseline: grayscale + autocontrast, psm 6.
    g = ImageOps.autocontrast(ImageOps.grayscale(img))
    texts.append(pytesseract.image_to_string(g, lang='eng', config='--psm 6'))
    texts.append(pytesseract.image_to_string(g, lang='eng', config='--psm 4'))
    # Upscale 2x if small side < 900.
    if min(img.size) < 900:
        big = img.resize((img.size[0] * 2, img.size[1] * 2))
        big = ImageOps.autocontrast(ImageOps.grayscale(big))
        texts.append(pytesseract.image_to_string(big, lang='eng', config='--psm 6'))
    return texts


def normalize_amount(s):
    if s is None:
        return None
    s = str(s).strip()
    if not s:
        return None
    s = s.replace(",", "")
    s = re.sub(r"(\d)[:;](\d{1,2})\b", r"\1.\2", s)
    m = re.search(r"(\d+)(?:\.(\d{1,2}))?$", s)
    if not m:
        return None
    whole = m.group(1)
    frac = (m.group(2) or "00").ljust(2, "0")
    return f"{int(whole)}.{frac[:2]}"


def is_excluded(line_upper):
    for kw in EXCLUDE_KEYWORDS:
        if kw in line_upper:
            return True
    return False


def find_amounts(text):
    return [m.group(0) for m in AMOUNT_RE.finditer(text)]


def extract_total_from_text(text):
    """Return best total amount string (not normalized) or None."""
    lines = [ln for ln in text.splitlines()]
    n = len(lines)

    for group in KEYWORD_GROUPS:
        for i, line in enumerate(lines):
            up = line.upper()
            if is_excluded(up):
                continue
            matched = None
            for kw in group:
                if kw in up:
                    matched = kw
                    break
            if not matched:
                continue
            # Avoid partial match of SUBTOTAL for TOTAL keyword.
            if matched == "TOTAL" and "SUBTOTAL" in up.replace(" ", ""):
                continue

            amounts = find_amounts(line)
            if amounts:
                # Prefer the last decimal-looking number in the line.
                dec = [a for a in amounts if "." in a]
                return dec[-1] if dec else amounts[-1]
            # Fallback: use last number on the next non-empty line.
            j = i + 1
            while j < n and not lines[j].strip():
                j += 1
            if j < n:
                next_up = lines[j].upper()
                if not is_excluded(next_up):
                    nxt_amounts = find_amounts(lines[j])
                    if nxt_amounts:
                        dec = [a for a in nxt_amounts if "." in a]
                        return dec[-1] if dec else nxt_amounts[-1]
    return None


def extract_total(texts):
    """Extract best total across OCR variants."""
    candidates = []
    for t in texts:
        c = extract_total_from_text(t)
        if c:
            norm = normalize_amount(c)
            if norm:
                candidates.append(norm)
    if not candidates:
        return None
    # Majority vote.
    counts = {}
    for c in candidates:
        counts[c] = counts.get(c, 0) + 1
    # Return the most common.
    return max(counts.items(), key=lambda x: (x[1], candidates.index(x[0]) * -1))[0]


DATE_PATTERNS = [
    re.compile(r"\b(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})\b"),
    re.compile(r"\b(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})\b"),
]

DATE_LABEL_RE = re.compile(r"\b(DATE|DATED|INVOICE\s*DATE|DOC\s*DATE|DAIE|DATA)\b", re.IGNORECASE)


def _plausible(y, m, d):
    try:
        y, m, d = int(y), int(m), int(d)
    except Exception:
        return False
    if y < 100:
        y += 2000
    if y < 2000 or y > 2035:
        return False
    if not (1 <= m <= 12):
        return False
    if not (1 <= d <= 31):
        return False
    return True


def _to_iso(y, m, d):
    y, m, d = int(y), int(m), int(d)
    if y < 100:
        y += 2000
    return f"{y:04d}-{m:02d}-{d:02d}"


def extract_dates_from_line(line):
    """Yield (y,m,d) iso strings from a line."""
    out = []
    for m in DATE_PATTERNS[0].finditer(line):
        a, b, c = m.group(1), m.group(2), m.group(3)
        # dd/mm/yyyy assumption
        if _plausible(c, b, a):
            out.append(_to_iso(c, b, a))
    for m in DATE_PATTERNS[1].finditer(line):
        a, b, c = m.group(1), m.group(2), m.group(3)
        # yyyy/mm/dd
        if _plausible(a, b, c):
            out.append(_to_iso(a, b, c))
    return out


def extract_date_from_text(text):
    lines = text.splitlines()
    labeled = []
    unlabeled = []
    for idx, ln in enumerate(lines):
        has_label = bool(DATE_LABEL_RE.search(ln))
        for iso in extract_dates_from_line(ln):
            if has_label:
                labeled.append((idx, iso))
            else:
                unlabeled.append((idx, iso))
    if labeled:
        # Prefer the first (top of receipt).
        return labeled[0][1]
    if unlabeled:
        return unlabeled[0][1]
    return None


def extract_date(texts):
    counts = {}
    first_seen = {}
    for t_idx, t in enumerate(texts):
        d = extract_date_from_text(t)
        if d:
            counts[d] = counts.get(d, 0) + 1
            if d not in first_seen:
                first_seen[d] = t_idx
    if not counts:
        return None
    return max(counts.items(), key=lambda x: (x[1], -first_seen[x[0]]))[0]


def process():
    files = sorted(glob.glob(os.path.join(IMG_DIR, "*")))
    results = []
    for fp in files:
        fn = os.path.basename(fp)
        try:
            texts = ocr_variants(fp)
            total = extract_total(texts)
            date = extract_date(texts)
        except Exception as e:
            print(f"ERROR {fn}: {e}")
            total = None
            date = None
        print(f"{fn}\tdate={date}\ttotal={total}")
        results.append((fn, date, total))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fn, d, t in results:
        ws.append([fn, d, t])
    wb.save(OUT_XLSX)
    print(f"Saved {OUT_XLSX}")


if __name__ == "__main__":
    process()
