def extract_date_from_text(text):
    lines = text.splitlines()
    labeled, unlabeled = [], []
    for idx, ln in enumerate(lines):
        has_label = bool(DATE_LABEL_RE.search(ln))
        for iso in extract_dates_from_line(ln):
            if has_label:
                labeled.append((idx, iso))
            else:
                unlabeled.append((idx, iso))
    if labeled:
        return labeled[0][1]
    if unlabeled:
        return unlabeled[0][1]
    return None


def vote(candidates):
    cleaned = [c for c in candidates if c]
    if not cleaned:
        return None
    counts = Counter(cleaned)
    best = counts.most_common(1)[0][1]
    for c in cleaned:
        if counts[c] == best:
            return c
    return cleaned[0]


def process():
